-- Scarlet Halls (map 1001): spawns, yells, doors and scripts for the ported Pandaria scripts
-- (tools/bfa/scarlet-halls.patch). Spawns come from the Pandaria 5.4.8 world DB (alexkulya),
-- which has the whole dungeon: this database only had a partial, shifted set and no kennel hounds,
-- guards, stakes, buckets, archery targets, cannons or books. Safe to run again.

-- 1) Spawns: replace everything on map 1001 except the two entrance Hooded Crusaders (2026_10_23_02).
DELETE FROM `creature_addon` WHERE `guid` IN (SELECT `guid` FROM `creature` WHERE `map`=1001 AND `guid` NOT IN (13241581, 13241582));
DELETE FROM `creature` WHERE `map`=1001 AND `guid` NOT IN (13241581, 13241582);
DELETE FROM `waypoint_data` WHERE `id` BETWEEN 1001000001 AND 1001000999;

-- Patrols (starving hounds with their watchmen, a few crusaders). Path id = spawn guid.

-- 2) Gameobjects: Lindon's gate, Braun's fire wall, Herod's Door (210480 replaces the old 101854),
--    the lever, the heroes' statues in Harlan's room, chairs and the Ancient Tome. The portal stays.
DELETE FROM `gameobject` WHERE `map`=1001 AND `guid`<>3300000000964;

-- 3) Yells and emotes (none existed for any Scarlet Halls NPC).
DELETE FROM `creature_text` WHERE `CreatureID` IN (58632, 59150, 59163, 59191, 59303, 64738);

-- 4) Scripts. These NPCs move from SmartAI to the C++ scripts in scarlet-halls.patch; their SmartAI rows
--    go (including the Hungry Dog action list from 2026_10_23_03, now done in C++ with the same 4 s cap).
DELETE FROM `smart_scripts` WHERE `source_type`=0 AND `entryorguid` IN (58876, 58674, 65379, 59163, 59191, 59175, 58726, 59293, 64738, 59303, 59309, 58632, 58998, 59150, 59155, 59198);
DELETE FROM `smart_scripts` WHERE `source_type`=9 AND `entryorguid`=5887600;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_starving_hound' WHERE `entry`=58876;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_angry_hound' WHERE `entry`=58674;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_bucket_of_meaty_dog_food', `npcflag`=16777216 WHERE `entry`=65379;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_reinforced_archery_target', `npcflag`=16777216 WHERE `entry`=59163;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_commander_lindon', `faction`=14 WHERE `entry`=59191;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_scarlet_master_archer', `faction`=14 WHERE `entry`=59175;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_scarlet_cannon_stalker', `unit_flags`=33554432, `flags_extra`=128 WHERE `entry`=58726;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_scarlet_cannoneer' WHERE `entry`=59293;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_scarlet_hooded_crusader' WHERE `entry`=64738;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='boss_houndmaster_braun' WHERE `entry`=59303;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_obedient_hound' WHERE `entry`=59309;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='boss_armsmaster_harlan' WHERE `entry`=58632;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_harlan_scarlet_defender' WHERE `entry`=58998;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='boss_flameweaver_koegler' WHERE `entry`=59150;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_book_case' WHERE `entry`=59155;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_dragon_breath_target', `unit_flags`=33554432, `flags_extra`=128 WHERE `entry`=59198;
-- helpers: invisible triggers and unselectable props, as in the Pandaria templates
UPDATE `creature_template` SET `flags_extra`=128 WHERE `entry` IN (58725, 58727, 66091);
UPDATE `creature_template` SET `unit_flags`=33554432 WHERE `entry` IN (58701, 60908);
-- Exploding Shot Stalker (summoned where Lindon's exploding shots land): burns the floor for 30 s
UPDATE `creature_template` SET `faction`=14, `unit_flags`=33685504, `flags_extra`=128 WHERE `entry`=59683;

-- Scarlet Treasurers drop a pile of Gold Coins when they die
DELETE FROM `smart_scripts` WHERE `source_type`=0 AND `entryorguid`=59241 AND `id`=1;

-- Template auras from the Pandaria DB: chained and speedy hounds, loot sparkle on the buckets and
-- archery targets, the Phalanx Defense guards, Lindon's and the archers' passives
DELETE FROM `creature_template_addon` WHERE `entry` IN (58674, 59163, 59175, 59191, 59299, 65379, 59683, 59198, 59209);

-- Greater Dragon's Breath is channelled on the Dragon Breath Target that circles Koegler
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId`=13 AND `SourceEntry`=113641;

DELETE FROM `spell_script_names` WHERE `spell_id` IN (113029, 111894, 113436, 111394, 113959, 113641, 113364);

DELETE FROM `areatrigger_scripts` WHERE `entry`=7532;

-- 5) The instance had no script, so no boss states, doors or codex hand-in
UPDATE `instance_template` SET `script`='instance_scarlet_halls' WHERE `map`=1001;
