INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(58632, 0, 0, 'Ah-hah! Another chance to test my might.', 14, 0, 100, 0, 0, 29428, 0, 0, 'Harlan Intro'),
(58632, 1, 0, 'Bested... by the likes of...', 14, 0, 100, 0, 0, 29427, 0, 0, ''),
(58632, 2, 0, 'Hah-HAH!', 14, 0, 100, 0, 0, 29429, 0, 0, ''),
(58632, 3, 0, 'Tsk! You need more training.', 14, 0, 100, 0, 0, 29430, 0, 0, ''),
(58632, 4, 0, 'On your guard!', 14, 0, 100, 0, 0, 29426, 0, 0, ''),
(59150, 0, 0, 'Everything must burn. None shall know of the Scarlet Crusade\'s shame!', 14, 0, 100, 0, 0, 29524, 0, 0, 'KOEGLER_INTO'),
(59150, 1, 0, 'You, too, shall be charred to ash!', 14, 0, 100, 0, 0, 29522, 0, 0, 'KOEGLER_AGGRO'),
(59150, 2, 0, 'Purged by fire!', 14, 0, 100, 0, 0, 29528, 0, 0, 'KOEGLER_DRAGON_BREATH'),
(59150, 3, 0, '|TInterface\\Icons\\ability_warlock_inferno.blp:20|t%s begins to cast |cFFFF0000|Hspell:113364|h[Book Burner]|h|r!', 41, 0, 100, 0, 0, 0, 0, 0, 'KOEGLER_BOOK_BURNER_ANN'),
(59150, 4, 0, '|TInterface\\Icons\\inv_misc_head_dragon_01.blp:20|t%s begins to cast |cFFFF0000|Hspell:113653|h[Greater Dragon\'s Breath]|h|r!', 41, 0, 100, 0, 0, 0, 0, 0, 'KOEGLER_DRAGON_BREATH_ANN'),
(59150, 5, 0, 'My fire... has gone out..', 14, 0, 100, 0, 0, 29523, 0, 0, 'KOEGLER_DEATH'),
(59163, 1, 0, 'Follow and use the shield as cover!', 41, 0, 100, 0, 0, 0, 0, 0, 'INSTANCE_REINFORCEMENT_ANN'),
(59191, 1, 0, 'Keep firing! Let none escape!', 12, 0, 100, 0, 0, 29437, 0, 0, 'LINDON_RANGE'),
(59191, 2, 0, 'Another down.  Do not relent!', 12, 0, 100, 0, 0, 29438, 0, 0, 'LINDON_FIRE_ARROWS'),
(59191, 3, 0, 'Blades at the ready men!', 12, 0, 100, 0, 0, 0, 0, 0, 'LINDON_MELEE'),
(59303, 0, 0, 'Ah, fresh meat for the dogs.', 12, 0, 100, 0, 0, 27550, 0, 0, ''),
(59303, 1, 0, 'I bleed... haha... but I won\'t die!', 12, 0, 100, 0, 0, 27544, 0, 0, ''),
(59303, 2, 0, 'What? No, no! Stop!  Obey your master!', 12, 0, 100, 0, 0, 27545, 0, 0, ''),
(59303, 3, 0, 'I let the dogs out!', 12, 0, 100, 0, 0, 27551, 0, 0, ''),
(59303, 4, 0, 'Stupid animals!  I\'ll put you down after I kill these weaklings.', 12, 0, 100, 0, 0, 27543, 0, 0, ''),
(64738, 0, 0, 'There are a lot of corpses out there.  Nicely done, $p.', 12, 0, 100, 0, 0, 0, 0, 0, 'HOODED_CRUSADER_INTRO'),
(64738, 1, 0, 'Did you get the codex?', 12, 0, 100, 0, 0, 0, 0, 0, 'HOODED_CRUSADER_CODEX');
